package com.bank.grid;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

// Finds all watchlist patterns embedded as adjacent-cell paths in the grid.
public class PatternGridSearch {

    private static final Logger log = Logger.getLogger(PatternGridSearch.class.getName());

    public List<String> findPatterns(char[][] board, String[] watchlist) {
        TrieNode root = buildTrie(watchlist);
        List<String> found = new ArrayList<>();
        for (int r = 0; r < board.length; r++) {
            for (int c = 0; c < board[0].length; c++) {
                dfs(board, r, c, root, found);
            }
        }
        log.info("Patterns matched in grid: " + found);
        return found;
    }

    private TrieNode buildTrie(String[] words) {
        TrieNode root = new TrieNode();
        for (String w : words) {
            TrieNode node = root;
            for (char c : w.toCharArray()) {
                node = node.children.computeIfAbsent(c, k -> new TrieNode());
            }
            node.word = w; // store full word on terminal node
        }
        return root;
    }

    private void dfs(char[][] board, int r, int c, TrieNode node, List<String> found) {
        if (r < 0 || c < 0 || r >= board.length || c >= board[0].length) return;
        char ch = board[r][c];
        if (ch == '#') return;                 // already visited on this path
        TrieNode next = node.children.get(ch);
        if (next == null) return;              // prune: no word shares this prefix

        if (next.word != null) {               // reached a complete pattern
            found.add(next.word);
            next.word = null;                  // avoid duplicate collection
        }
        board[r][c] = '#';                     // mark visited
        dfs(board, r + 1, c, next, found);
        dfs(board, r - 1, c, next, found);
        dfs(board, r, c + 1, next, found);
        dfs(board, r, c - 1, next, found);
        board[r][c] = ch;                      // backtrack: restore cell
    }
}
