package com.bank.grid;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class GridSearchDemo {

    private static final Logger log = Logger.getLogger(GridSearchDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) {
            root.removeHandler(h);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Fraud Pattern Grid Search");
        char[][] board = {
            {'F', 'R', 'A', 'U'},
            {'X', 'A', 'U', 'D'},
            {'R', 'I', 'S', 'K'},
            {'Y', 'K', 'E', 'D'}
        };
        String[] watchlist = {"FRAUD", "RISK", "AUD", "SAFE"};
        PatternGridSearch service = new PatternGridSearch();
        service.findPatterns(board, watchlist);
    }
}
